const CALLBACK_URL = "http://localhost:3000/auth/google/callback";

function googleConfig(env) {
  const need = (name) => {
    const value = env[name];
    if (!value) throw new Error(`${name} is not set. Add it to your .env file.`);
    return value;
  };
  return {
    provider: "google",
    clientId: need("GOOGLE_CLIENT_ID"),
    clientSecret: need("GOOGLE_CLIENT_SECRET"),
    allowedRedirectUris: [CALLBACK_URL],
  };
}

try {
  googleConfig({ GOOGLE_CLIENT_ID: "task-api.apps.googleusercontent.com", GOOGLE_CLIENT_SECRET: "" });
