const pending = new Map([
  ["login-1", { state: "s-1111", codeVerifier: "verifier-1", expiresAt: 1000 }],
  ["login-2", { state: "s-2222", codeVerifier: "verifier-2", expiresAt: 1000 }],
  ["login-3", { state: "s-3333", codeVerifier: "verifier-3", expiresAt: 500 }],
]);

function takeVerifiedLogin(loginId, receivedState, now) {
  const login = loginId === undefined ? undefined : pending.get(loginId);
  if (loginId !== undefined) pending.delete(loginId);
  if (login === undefined || login.expiresAt < now || login.state !== receivedState) {
    throw new Error("OAuth state verification failed.");
  }
  return login.codeVerifier;
}

const tries = [
  ["login-1", "s-1111"], ["login-1", "s-1111"], ["login-2", "forged"],
  ["login-2", "s-2222"], ["login-3", "s-3333"], [undefined, "s-1111"],
];
for (const [loginId, state] of tries) {
  try {
    console.log("ok", takeVerifiedLogin(loginId, state, 800));
  } catch (error) {
    console.log(error.message);
  }
