function readCallback(query) {
  const code = query.code;
  if (typeof code !== "string" || code === "") {
    return { status: 400, error: "Sign-in was cancelled" };
  }
  const state = typeof query.state === "string" ? query.state : "";
  return { status: 200, code, state };
}

